<template><article class="detail-card person-card"><header><h2>{{ title }}</h2></header><div class="person-heading"><span>{{ (person?.name||'?').charAt(0).toUpperCase() }}</span><div><strong>{{ person?.name||'Deleted user' }}</strong><small>User #{{ person?.id||'—' }}</small></div></div><div class="person-lines"><p><span>Phone</span><b>{{ person?.phone||'Not provided' }}</b></p><p><span>Email</span><b>{{ person?.email||'Not provided' }}</b></p><p><span>Address</span><b>{{ person?.address||'Not provided' }}</b></p></div><Link v-if="person?.id" :href="route('users.show',person.id)" class="panel-link">View profile <span>→</span></Link></article></template><script setup>import{route}from'ziggy-js';defineProps({title:String,person:Object});</script>
